def calculate_date_time(df):
    import pandas as pd
    df = df.drop_duplicates(subset='id')
    # 假设 df 是你的 DataFrame，时间列是 'create_date_time'
    df['create_date_time'] = pd.to_datetime(df['发布时间'].apply(lambda x:x.replace('-', '/')))

    # 获取最晚的日期时间（保留完整时间戳）
    latest_datetime = df['create_date_time'].max()

    # 计算7天前的 00:00:00（确保包含完整7天）
    start_date = (latest_datetime - pd.Timedelta(days=6)).normalize()

    # 筛选最近7天的数据（包含 start_date 00:00:00 到 latest_datetime）
    mask = (df['create_date_time'] >= start_date) & (df['create_date_time'] <= latest_datetime)
    recent_data = df.loc[mask].copy()

    # 提取日期（去掉时间部分）
    recent_data['date'] = recent_data['create_date_time'].dt.normalize()

    # 按日期分组统计行数，并按日期降序排序
    daily_counts = recent_data['date'].value_counts().sort_index(ascending=False)

    # 生成完整的7天日期范围（从 start_date 到 latest_date.normalize()）
    date_range = pd.date_range(start=start_date, end=latest_datetime.normalize(), freq='D')

    # 确保日期范围是7天（防止数据不足7天）
    if len(date_range) < 7:
        date_range = pd.date_range(end=latest_datetime.normalize(), periods=7, freq='D')

    # 构建结果字典，按从新到旧排序（第1天=最新一天）
    result = {}
    for i, date in enumerate(date_range[::], 1):  # 反转，使最新一天是第1天
        count = daily_counts.get(date, 0)
        result[f"第{i}天"] = int(count)

    return result


def get_files_in_folder(folder_path):
    # 获取所有的csv数据样本，并返回csv_list
    file_list = []
    for root, dirs, files in os.walk(folder_path):
        for file_path in files:
            if "csv" in file_path:
                file_list.append(os.path.join(root, file_path))
    return file_list

def filter_df(df, filter_dict, file_path):

    def translate_filter_value(filter_col, filter_value, file_path):
        # 依据平台翻译筛选值，以匹配平台的实际情况
        if "xhs" in file_path:
            platform = 'xhs'
        elif 'wb' in file_path:
            platform = 'wb'
        else:
            platform = 'wb'

        rename_dict = {
            'xhs_gender': 'user_gender',
            'xhs_gender_male': 0,
            'xhs_gender_female': 1,
            'xhs_gender_nogender': 2,
            'wb_gender': 'user_gender',
            'wb_gender_male': 'm',
            'wb_gender_female': 'f',
            'wb_gender_nogender': '',
        }
        return rename_dict[f'{platform}_{filter_col}'], rename_dict[f'{platform}_{filter_col}_{filter_value}']


    if len(filter_dict) == 0:
        return df
    else:
        for filter_col in filter_dict:
            filter_value = filter_dict[filter_col]
            trans_col, trans_value = translate_filter_value(filter_col, filter_value, file_path)
            if trans_col not in df.columns:
                print(f"错误筛选属性：{filter_col}，{file_path}")
            else:
                if trans_value not in list(df[trans_col]):
                    print(f"错误筛选值，不存在该值：{filter_col}：{filter_value}，{file_path}")
                else:
                    df = df[df[trans_col] == trans_value]
                    print(f"成功筛选值：{filter_col}：{filter_value}，{file_path}")
    df = df.reset_index()
    return df



def analyiz_data_file(file_path, filter_dict = dict()):
    try:
        file_path = file_path.replace(".xlsx", '.csv')
        try:
            df = pd.read_csv(file_path, encoding='utf_8_sig')
        except:
            df = pd.read_csv(file_path, encoding='gbk')
    except:
        file_path = file_path.replace(".csv", '.xlsx')
        df = pd.read_excel(file_path)
    df = df.reset_index(drop=True)
    event_keyword = event = file_path.split(f'{os.sep}')[-1].split('.csv')[0].split('_')[0]
    if 'wb' in file_path:
        platform = 'wb'
    elif 'xhs' in file_path:
        platform = 'xhs'
    elif 'baidu' in file_path:
        platform = 'baidu'
    else:
        platform = 'wb'
        print('默认采用wb平台')
    df = df.fillna('')
    if 'content' not in df.columns and '微博正文' in df.columns:
        df['content'] = df['微博正文']

    df = filter_df(df, filter_dict, file_path)


    result = {}
    result['event'] = event


    # 贴子数量变化曲线
    if 'time' in df.columns:
        df['发布时间'] = df['time']
    if 'create_date_time' in df.columns:
        df['发布时间'] = df['create_date_time']
    df = df.drop_duplicates(subset='id')
    df = df[df['发布时间'] != '']
    df = df.reset_index(())


    df_time = df[df['发布时间'] != '']
    result['近七天帖子数'] = calculate_date_time(df_time)

    if 'ip' in df.columns and len(df[df['ip']!=''])!=0:
        df['发布位置'] = df['ip']

    # 地域分布
    df_area = df[df['发布位置']!='']
    area_num_dict = {
        "北京": 0,
        "天津": 0,
        "上海": 0,
        "重庆": 0,
        "河北": 0,
        "山西": 0,
        "辽宁": 0,
        "吉林": 0,
        "黑龙江": 0,
        "江苏": 0,
        "浙江": 0,
        "安徽": 0,
        "福建": 0,
        "江西": 0,
        "山东": 0,
        "河南": 0,
        "湖北": 0,
        "湖南": 0,
        "广东": 0,
        "海南": 0,
        "四川": 0,
        "贵州": 0,
        "云南": 0,
        "陕西": 0,
        "甘肃": 0,
        "青海": 0,
        "台湾": 0,
        "内蒙古": 0,
        "广西": 0,
        "西藏": 0,
        "宁夏": 0,
        "新疆": 0,
        "香港": 0,
        "澳门": 0,
    }
    china_num = 0
    if len(df_area) > 0:
        for area in area_num_dict.keys():
            area_num_dict[area] = len(df_area[df_area['发布位置']==area]) / len(df_area)
            china_num += len(df_area[df_area['发布位置']==area])
        area_num_dict['其他'] = (len(df_area) - china_num)/len(df_area)
    else:
        area_num_dict['其他'] = 0
    result['地域分布'] = area_num_dict
    result['有定位帖子占比'] = len(df_area) / len(df)

    # 三组统计数据
    result['总帖子数'] = len(df['id'].unique())
    result['总用户数'] = len(df['user_id'].unique())
    if len(df) > 0:
        if type(df.loc[0, '点赞数']) == str:
            df['点赞数'] = df['点赞数'].apply(lambda x:float(x.replace('+', '').replace('十', '0000').replace('百', '00').replace('千', '000').replace('万', '0000').replace('亿', '00000000')))
        total_hudong_num = df['点赞数'].sum()
        if '评论数' in df.columns:
            if type(df.loc[0, '评论数']) == str:
                df['评论数'] = df['评论数'].apply(lambda x: float(x.replace('+', '').replace('十', '0000').replace('百', '00').replace('千', '000').replace('万', '0000').replace('亿', '00000000')))
            total_hudong_num += df['评论数'].sum()
        if '转发数' in df.columns:
            if type(df.loc[0, '转发数']) == str:
                df['转发数'] = df['转发数'].apply(lambda x: float(x.replace('+', '').replace('十', '0000').replace('百', '00').replace('千', '000').replace('万', '0000').replace('亿', '00000000')))
            total_hudong_num += df['转发数'].sum()
    else:
        total_hudong_num = 0
    result['总互动数'] = float(total_hudong_num)

    # 词云编码

    result['词云编码'] = get_ciyun_df(df, platform=platform, output_image_path=file_path.replace('.csv', '_ciyun.png'))

    # 最早发布时间
    result['发布时间'] = df['发布时间'].min()

    return result

def get_analyiz_dir(data_dir='结果文件', filter_dict = dict()):
    data_file = get_files_in_folder(data_dir)
    data_total = {}

    for idx, data_path in enumerate(data_file):

        if True:
            result = analyiz_data_file(data_path, filter_dict=filter_dict)
            data_total[result['event']] = result

    with open(data_dir + f'{os.sep}analyiz_data.json','w', encoding='utf-8') as f:
        json.dump(data_total, f, ensure_ascii=False, indent=4)
    return data_dir + f'{os.sep}analyiz_data.json'

def init(*args, **kwargs):
    return

def forward(file_path, filter_dict=dict(), *args, **kwargs):
    return get_analyiz_dir(file_path, filter_dict=filter_dict), None
def forward_file(file_path:str, filter_dict=dict(), *args, **kwargs)->dict:
    # 文件级的处理，返回只有dict
    return analyiz_data_file(file_path, filter_dict=filter_dict)
